 _nextDungeonStep(expedition,start,target){if(start.x===target.x&&start.y===target.y)return null;const queue=[start],seen=new Set([pointKey(start)]),parent=new Map();let found=null;for(let cursor=0;cursor<queue.length&&!found;cursor++){const current=queue[cursor];for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const next={x:current.x+dx,y:current.y+dy},key=pointKey(next);if(seen.has(key)||expedition.tiles[next.y]?.[next.x]!==".")continue;seen.add(key);parent.set(key,current);if(next.x===target.x&&next.y===target.y){found=next;break}queue.push(next)}}if(!found)return null;let step=found;while(parent.has(pointKey(step))){const prior=parent.get(pointKey(step));if(prior.x===start.x&&prior.y===start.y)break;step=prior}return{...step,facing:step.x<start.x?"left":step.x>start.x?"right":step.y<start.y?"up":"down"}}
 _moveDisconnectedFollowers(room){const expedition=room.expedition,leader=this.sessions.get(room.leaderId);if(!expedition||expedition.battle||!leader?.dungeonPosition)return;for(const id of room.members){const member=this.sessions.get(id);if(!member||member.connected||!member.dungeonPosition||this.now()-(member.lastAiMove??0)<300)continue;const target=expedition.exitReached?expedition.exit:leader.dungeonPosition,next=this._nextDungeonStep(expedition,member.dungeonPosition,target);if(!next)continue;member.dungeonPosition=next;member.lastAiMove=this.now();this._broadcast(room,{type:"expeditionMoved",playerId:member.playerId,position:{...next},autoPilot:true});this._resolveLanding(room,member)}}
 _spawnPosition(count){const positions=[{x:50,y:76,facing:"down"},{x:36,y:67,facing:"right"},{x:64,y:67,facing:"left"},{x:50,y:55,facing:"down"}];return{...(positions[Math.max(0,count-1)]??positions[0])}}
